function grape(cx: number, cy: number, f: string, r = 2.1): MojiArt {
  return [
    { t: 'c', cx, cy, r, f },
    { t: 'c', cx: cx - r * 0.35, cy: cy - r * 0.35, r: r * 0.3, f: M.purple.l },
  ];
}
